{"taskId":"HC-902","attempt":1,"summary":"Format non-negative integer minutes with correct singular/plural wording and reject invalid inputs with TypeError.","patches":[{"path":"src/hc-902.mjs","baseSha256":"0EC59C7B026D84C68031FDA0B3489040115E7404DEC2CE20CB2A70388E1D7FEC","content":"export function formatDuration(minutes) {
  if (!Number.isInteger(minutes) || minutes < 0) {
    throw new TypeError('minutes must be a non-negative integer');
  }

  return `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`;
}
"}],"limitations":["Required test/hc-902.test.mjs was not supplied; tests were not run as instructed."]}
